css:
/* Сменное слово в заголовке. Слова в одной ячейке inline-grid: ширина и высота — по самому длинному,
   поэтому смена не двигает строку (CLS 0). Маска — overflow: clip с запасом под хвосты букв (у, р, д, Й). */
.hwr {
  --hwr-in: 520ms;                          /* входящее слово: подъём из-под маски */
  --hwr-out: 360ms;                         /* уходящее — быстрее, ~70 % от входа */
  --hwr-ease-in: cubic-bezier(.16, 1, .3, 1); /* вход — резкий старт, мягкая остановка */
  --hwr-ease-out: cubic-bezier(.7, 0, .84, 0); /* уход — разгон */
  display: inline-grid;
  justify-items: var(--hwr-align, start);  /* центрированный заголовок: --hwr-align: center */
  padding-block: .12em; margin-block: -.12em; /* запас маски под хвосты букв, строка не растёт */
  overflow: hidden;
  overflow: clip;
  color: var(--hwr-color, inherit);         /* цвет слова — только text или link: primary и accent — заливки, не цвет текста */
}
.hwr__word { grid-area: 1 / 1; white-space: nowrap; }
.hwr:not(.is-live) .hwr__word:not(.is-in) { visibility: hidden; } /* без JS видно только первое слово, остальные держат ширину */
/* Ждущие слова стоят под маской мгновенно (transition: none), без проезда через видимую область */
.hwr.is-live .hwr__word { transform: translateY(110%); opacity: 0; transition: none; }
.hwr.is-live .hwr__word.is-in {
  transform: none; opacity: 1;
  transition: transform var(--hwr-in) var(--hwr-ease-in) 60ms, opacity calc(var(--hwr-in) * .5) linear 60ms; /* перехлёст с уходом */
}
.hwr.is-live .hwr__word.is-out {
  transform: translateY(-110%); opacity: 0;
  transition: transform var(--hwr-out) var(--hwr-ease-out), opacity var(--hwr-out) linear;
}
/* Кнопка паузы: 32px, видимый фокус. Место за ней занято с первого кадра — появление не сдвигает первый экран */
.hwr__pause {
  display: inline-grid; place-items: center;
  width: 32px; height: 32px; margin-top: 8px; padding: 0;
  border: 1px solid var(--border, #c9ced8); border-radius: 50%;
  background: transparent; color: var(--text, #15171c); cursor: pointer;
}
.hwr__pause[hidden] { display: inline-grid; visibility: hidden; }
.hwr__pause::before { content: ""; width: 8px; height: 10px; box-sizing: border-box; border-inline: 3px solid currentColor; } /* пауза */
.hwr__pause[aria-pressed="true"]::before { width: 9px; border: 0; background: currentColor; clip-path: polygon(0 0, 100% 50%, 0 100%); } /* пуск */
.hwr__pause:focus-visible { outline: 2px solid var(--primary, #2446d8); outline-offset: 2px; }
/* Уровень 1 (убрать): смены нет, стоит первое слово; кнопке паузы нечего делать — она не занимает места */
@media (prefers-reduced-motion: reduce) {
  .hwr.is-live .hwr__word { transition: none !important; }
  .hwr__pause, .hwr__pause[hidden] { display: none; }
}

js:
// Сменное слово: без зависимостей. Пауза кнопкой, вне экрана и в скрытой вкладке; два круга и остановка на первом слове.
(() => {
  const root = document.querySelector('[data-hwr]');
  const btn = document.querySelector('.hwr__pause');
  const words = root ? [...root.querySelectorAll('.hwr__word')] : [];
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  if (words.length < 2) return;
  const EVERY = 2600, LAPS = 2; // смена раз в 2,6 с; кругов до остановки
  let cur = 0, left = words.length * LAPS, timer = 0, paused = false, seen = true;
  const go = (i) => {
    const old = words[cur], next = words[i];
    old.classList.replace('is-in', 'is-out');
    setTimeout(() => old.classList.remove('is-out'), 450); // ушло — встаёт под маску без проезда
    next.classList.add('is-in');
    cur = i;
  };
  const plan = () => { // следующий шаг, только если можно двигаться
    clearTimeout(timer);
    if (paused || !seen || document.hidden || reduce.matches || left <= 0) return;
    timer = setTimeout(() => { go((cur + 1) % words.length); if (--left <= 0) setPaused(true); else plan(); }, EVERY); // круги кончились — «на паузе»
  };
  const setPaused = (v) => {
    paused = v;
    btn?.setAttribute('aria-pressed', String(v)); // подпись постоянная, состояние — aria-pressed
    if (!v && left <= 0) left = words.length * LAPS; // «пуск» после остановки — ещё два круга
    plan();
  };
  btn?.addEventListener('click', () => setPaused(!paused));
  new IntersectionObserver((es) => { seen = es[es.length - 1].isIntersecting; plan(); }).observe(root); // вне экрана — стоим
  document.addEventListener('visibilitychange', plan);
  reduce.addEventListener('change', () => { if (reduce.matches && cur) go(0); plan(); }); // включили «меньше движения» — вернуть первое слово
  root.classList.add('is-live');
  if (btn) btn.hidden = false;
  if (!reduce.matches) plan();
})();
